import heapq


def _interval_solver(capacity, largest_tie=False):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        if len(mandatory) > k or mandatory & blocked:
            return {"error": "impossible"}
        best_value = None
        best_ids = None
        eligible = [job for job in jobs if job["id"] not in blocked]
        for subset in combinations(eligible, k):
            ids = tuple(sorted(job["id"] for job in subset))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            active = []
            valid = True
            for job in sorted(subset, key=lambda row: (row["start"], row["end"], row["id"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                (value == best_value and
                 ((ids > best_ids) if largest_tie else (ids < best_ids)))):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    def solve(data):
        winners = {}
        cutoff = data.get("cutoff", 10**9)
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            rank = (event.get("revision", 0), position)
            if event_id not in winners or rank > winners[event_id][0]:
                winners[event_id] = (rank, event)
        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            allowed = [row for row in packages[name]
                       if row["version"] not in blocked.get(name, [])
                       and (name not in pins or row["version"] == pins[name])]
            choices.append([None] + sorted(allowed, key=lambda r: r["version"]))

        best_vector = None
        best_versions = None
        for selection in product(*choices):
            selected = {name: row for name, row in zip(names, selection)
                        if row is not None}
            versions = {name: row["version"] for name, row in selected.items()}
            if any(name not in versions or not low <= versions[name] <= high
                   for name, (low, high) in roots.items()):
                continue
            edges = {name: [] for name in selected}
            valid = True
            for name, row in selected.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if other not in versions or not dep["min"] <= versions[other] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                if name not in selected:
                    valid = False
                    break
                reachable.add(name)
                stack.extend(edges[name])
            if not valid or reachable != set(selected):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(visit(name) for name in selected):
                continue

            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector, best_versions = vector, versions
        if best_vector is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        indices = {node: i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        mask = 0
        if data["source"] in indices:
            mask |= 1 << indices[data["source"]]
        start_state = (data["source"], mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"],) + start_state]
        while queue:
            time, node, seen, remaining = heapq.heappop(queue)
            state = (node, seen, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and seen == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                traversals = [(edge["duration"], remaining)]
                if remaining:
                    traversals.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
                for duration, left in traversals:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    dest = edge["v"]
                    new_seen = seen
                    if dest in indices:
                        new_seen |= 1 << indices[dest]
                    new_state = (dest, new_seen, left)
                    if arrival < distances.get(new_state, float("inf")):
                        distances[new_state] = arrival
                        heapq.heappush(queue, (arrival,) + new_state)
        return {"arrival": None}
    return solve


